"""Apply bounded, snapshotted publication edits; no formal ARS authorization certificate."""
from pathlib import Path
import json,re,hashlib,argparse
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def apply(output):
    output=Path(output);before=json.loads((output/'manuscript-before.json').read_text());changes=[]
    final=ROOT/'paper/final'
    if not (final/'corrected_results.tex').exists():raise ValueError('Generate verified additions first')
    def save(path,text):
        old=path.read_text();expected=before.get(str(path))
        if expected and sha(path)!=expected:raise ValueError('Draft drift since snapshot: '+str(path))
        path.write_text(text);changes.append(dict(path=str(path),before_sha256=hashlib.sha256(old.encode()).hexdigest(),after_sha256=sha(path)))
    def replace_once(text,old,new):
        if text.count(old)!=1:raise ValueError('Exact revision anchor not unique: '+old[:80])
        return text.replace(old,new,1)
    p=final/'journal_main_v2.tex';s=p.read_text()
    s=replace_once(s,'The second contribution is a reproducible, assumption-sensitive portfolio translation.','The second contribution is a reproducible, assumption-sensitive portfolio translation. The following introductory sensitivities describe the preserved historical version; Section~\\ref{sec:corrected} reports the completed corrected-input benchmark and alternatives.')
    s=replace_once(s,'a full source rebuild remains pending.','the full Freddie source rebuild and dependent rerun are now complete (Section~\\ref{sec:corrected}).')
    s=replace_once(s,'A planned forty-scenario corrected-source comparison crosses five assumed shares, two response conversions, two gap treatments, and these two references; the legacy additive-survival specification is a separate benchmark. Scenario code does not constitute completed source runs, and no revised dollar estimate is supplied here.','The completed forty-scenario corrected-source comparison crosses five assumed shares, two response conversions, two gap treatments, and these two references; the additive-survival specification is a separate benchmark. Section~\\ref{sec:corrected} reports the accepted results and their retained identification limits.')
    s=s.replace('its chronological alignment awaits the full source audit.','its original chronological alignment is not certified by preserving those legacy scores. The completed corrected-input audit and new scores are reported separately in Section~\\ref{sec:corrected}.')
    s=replace_once(s,'An audited source rebuild, sale-reason data, broader collateral coverage, and untouched loan-level evaluation remain needed','The completed source rebuild resolves the declared reconstruction checks; sale-reason data, broader collateral coverage, and untouched loan-level evaluation remain needed')
    s=replace_once(s,'\\section{Results and Retrospective Validation}\\label{sec:results}','\\section{Results and Retrospective Validation}\\label{sec:results}\n\nThe original numerical tables and uncertainty bands below retain their historical input versions. The completed corrected-source comparison follows in Section~\\ref{sec:corrected}; historical values are not transferred to that rerun.')
    s=replace_once(s,'\\section{Policy Implications}\\label{sec:policy}','\\input{corrected_results}\n\n\\section{Policy Implications}\\label{sec:policy}');save(p,s)
    p=final/'review_appendix.tex';s=p.read_text().replace('describes the pending source rebuild and separate development candidate.','describes the historical pilot and development candidate; Appendix~\\ref{app:correcteddiagnostics} reports the completed rebuild and new diagnostics.').replace('its chronological alignment awaits the full source audit.','its original chronological alignment is not certified by retaining those legacy scores; corrected-input scores are reported in Appendix~\\ref{app:correcteddiagnostics}.').replace('or the unresolved source rebuild.','or the later corrected-source rerun.')
    s+='\n\\input{corrected_diagnostics}\n';save(p,s)
    p=final/'rebuild_audit_detail.tex';s=p.read_text();s=replace_once(s,'The ingestion repairs establish two code defects without establishing their full empirical effect.','The following pilot and age-only recombination describe the historical audit stage. The completed twenty-quarter Freddie rebuild, new scores, bridge and uncertainty diagnostics are reported in Appendix~\\ref{app:correcteddiagnostics}. The ingestion repairs established two code defects without, at that stage, establishing their full empirical effect.')
    s=s.replace('Source checks for duplicate loan-months, gaps, first-observation payoffs that fall back to original principal, and overlapping file membership remain incomplete across the full panel.','At that historical stage, checks for duplicate loan-months, gaps, first-observation payoff fallback and overlapping file membership were incomplete across the full panel.').replace('A full audited source rebuild and its dependent calibration and simulation reruns remain pending.','The subsequent Freddie rebuild and dependent reruns are complete; original-principal fallback remains an explicit assumption where the preceding balance is unobserved.');save(p,s)
    short=r'''\noindent From June 2022 through November 2025, agency-MBS caps exceeded the net holdings decline by\$764.7 billion. This accounting gap is not a causal lock-in estimate; allocating the published May2022 projection gives an expectations-relative gap of\$87.8--\$186.8 billion. A completed twenty-quarter Freddie reconstruction restricts the simulation frame to original360-month fixed-rate mortgages and audits chronology, eligibility, cohort histories, competing terminations and principal accounting. With inherited parameters, the corrected hard-maximum benchmark gives\$16.2 billion in reported OFF-minus-ON principal, or\$14.3 billion in closed-pool cash. The historical\$42.6 billion calculation remains version specific. Sequential substitutions show the largest change when pre-May burnout and fixed-cohort denominator initialization replace legacy initialization; they do not identify a pure parser effect. Mixtures assuming75\% sensitivity and an illustrative positive-gap response give\$49.6 and\$57.6 billion under inherited and matched-OFF references. Neither share nor reference is estimated. On4,998 previously examined cohort-months, both mixtures improve error relative to the hard-maximum and additive ON benchmarks, but remain worse than the simple cohort-speed baseline. Fresh floor measurement inference is reported separately from structural sensitivity. Missing early histories remain unknown. Imported-response validity, floor transport, sale/refinance classification and SOMA representativeness remain unresolved; computational acceptance does not establish a preferred amount, total uncertainty or causal identification.'''
    short=short.replace('by\\$','by \\$').replace('of\\$','of \\$').replace('gives\\$','gives \\$').replace('assuming75','assuming 75').replace('On4,998','On 4,998').replace('May2022','May 2022').replace('original360','original 360')
    short=re.sub(r'(?<=[A-Za-z])(?=[0-9])',' ',short)
    long=short+r''' The retained historical sensitivities belong to their original sample and floor mapping. The completed40-scenario matrix varies share, response conversion, rate-gap treatment and reference schedule without selecting a model from the examined outcomes. The source audit retains57 loans with\$21.870 million original principal whose pre-May histories are unknown; none enters the May starting portfolio. The corrected primary2018 floor read uses96 cohort-months and24 strata, with only5.10 exposure-effective clusters and no qualifying cohort mean age at least24 months. Its annualized end-exposure payoff-speed ratio is4.688\%, distinct from an observed beginning-balance hazard or purely involuntary turnover. Stratum and month clustering address different dependence assumptions; their inference does not encompass moving-share, response-calibration or portfolio-transport uncertainty. Reported dollars rescale each simulated leg to observed holdings each month, while closed-pool principal cash uses unscaled simulated payments. Neither measure identifies the actual contribution of the covered collateral to SOMA runoff.'''
    for a in ['completed40','retains57','primary2018','uses96','and24','only5.10','least24','is4.688']:
        long=long.replace(a,re.sub(r'(?<=[A-Za-z])(?=[0-9])',' ',a))
    short=re.sub(r'([A-Za-z])(\\\$)',r'\1 \2',short)
    long=re.sub(r'([A-Za-z])(\\\$)',r'\1 \2',long)
    for name,abstract in [('paper_final_v1.tex',short),('paper_final_v1_long_abstract.tex',long)]:
        p=final/name;s=p.read_text();start=s.index('\\begin{abstract}')+len('\\begin{abstract}');end=s.index('\\end{abstract}',start)
        s=s[:start]+'\n'+abstract+'\n'+s[end:];s=s.replace('October 13, 2026','October 14, 2026');save(p,s)
    record=dict(status='local_revision_applied',scope='Author-authorized post-rerun analysis and manuscript update',changed=changes,abstracts_regenerated=True,historical_values_retained=True,ars_formal_integrity_pass_claimed=False)
    (output/'manuscript_revision.json').write_text(json.dumps(record,indent=2)+'\n')
    print('Applied bounded manuscript and abstract revision; prior sources preserved in manuscript-before.zip')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--output',required=True);apply(p.parse_args().output)
